package com.nobody.ultraai;import android.os.Bundle;import android.widget.ScrollView;import android.widget.TextView;import androidx.appcompat.app.AppCompatActivity;public class CrashActivity extends AppCompatActivity{@Override protected void onCreate(Bundle savedInstanceState){super.onCreate(savedInstanceState);String err=getIntent().getStringExtra("error");ScrollView sv=new ScrollView(this);TextView tv=new TextView(this);tv.setText("CRASH DETECTED:\n\n"+err);tv.setTextColor(0xFFFF0000);tv.setTextSize(16);tv.setPadding(30,30,30,30);sv.addView(tv);setContentView(sv);}}
